var out=[],seen={};
function clean(v){return String(v||"").replace(/<[^>]+>/g," ").replace(/\s+/g," ").replace(/^\s+|\s+$/g,"");}
function abs(u){
    u=String(u||"").replace(/&amp;/g,"&").replace(/^\s+|\s+$/g,"");
    if(!u)return"";
    if(/^magnet:\?/i.test(u)||/^https?:\/\//i.test(u))return u;
    if(u.indexOf("//")===0)return "https:"+u;
    if(u.charAt(0)==="/")return backend+u;
    return backend+"/"+u.replace(/^\.\//,"");
}
function hash(v){
    var m=String(v||"").match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    if(!m)m=String(v||"").match(/([A-Fa-f0-9]{40})/);
    return m?String(m[1]).toUpperCase():"";
}
function add(title,desc,href){
    title=clean(title);desc=clean(desc);href=abs(href);
    if(!title||!href)return;
    var h=hash(href),key=String(h||href).toUpperCase();
    if(seen[key])return;seen[key]=1;
    var magnet=/^magnet:\?/i.test(href)?href:"";
    if(!magnet&&h)magnet="magnet:?xt=urn:btih:"+h+"&dn="+encodeURIComponent(title);
    out.push({title:title,desc:desc,url:magnet||href,magnet:magnet,seeders:-1,peers:-1,date:""});
}
